s.eventHistory=s.eventHistory.slice(0,100);
log(event.title+' — '+result);
const nextEvent=makeEvent();
const currentMinute=Math.floor(dayElapsedMs/(dayLength*1000)*1440);
nextEvent.minute=Math.max(nextEvent.minute,Math.min(1439,currentMinute+30));
